data.prepare:
const params = Editor.getParams();

const data = Editor.getLoadedData()['population_source_dataset'].result_data[0].rows;

const config = {
    data: data.map(el => ({
        state: el.data[0],
        age: el.data[1],
        population: el.data[2]
    })),
    backgroundColor: params.backgroundColor?.[0] ?? '',
};

module.exports = {
    render: Editor.wrapFn({
        fn: function(dimensions, config) {
            const data = config.data;
            const width = Math.min(dimensions.width, dimensions.height) - 20;
            const height = width;
            const innerRadius = 180;
            const outerRadius = Math.min(width, height) / 2;

            // Stack the data into series by age
            const series = d3.stack()
                .keys(d3.union(data.map(d => d.age))) // distinct series keys, in input order
                .value(([, D], key) => D.get(key).population) // get value for each series key and stack
                (d3.index(data, d => d.state, d => d.age)); // group by stack then series key

            const arc = d3.arc()
                .innerRadius(d => y(d[0]))
                .outerRadius(d => y(d[1]))
                .startAngle(d => x(d.data[0]))
                .endAngle(d => x(d.data[0]) + x.bandwidth())
                .padAngle(1.5 / innerRadius)
                .padRadius(innerRadius);

            // An angular x-scale
            const x = d3.scaleBand()
                .domain(data.map(d => d.state))
                .range([0, 2 * Math.PI])
                .align(0);

            // A radial y-scale maintains area proportionality of radial bars
            const y = d3.scaleRadial()
                .domain([0, d3.max(series, d => d3.max(d, d => d[1]))])
                .range([innerRadius, outerRadius]);

            const color = d3.scaleOrdinal()
                .domain(series.map(d => d.key))
                .range(d3.schemeSpectral[series.length])
                .unknown("#ccc");

            // A function to format the value in the tooltip
            const formatValue = x => isNaN(x) ? "N/A" : x.toLocaleString("en")

            const svg = d3.create("svg")
                .attr("width", width)
                .attr("height", height)
                .attr("viewBox", [-width / 2, -height / 2, width, height])
                .attr("style", "font: 10px sans-serif;");

            // A group for each series, and a rect for each element in the series
            svg.append("g")
                .selectAll()
                .data(series)
                .join("g")
                .attr("fill", d => color(d.key))
                .selectAll("path")
                .data(D => D.map(d => (d.key = D.key, d)))
                .join("path")
                .attr("d", arc)
                .append("title")
                .text(d => `${d.data[0]} ${d.key}\n${formatValue(d.data[1].get(d.key).population)}`);

            // x axis
            svg.append("g")
                .attr("text-anchor", "middle")
                .selectAll()
                .data(x.domain())
                .join("g")
                .attr("transform", d => `
                    rotate(${((x(d) + x.bandwidth() / 2) * 180 / Math.PI - 90)})
                    translate(${innerRadius},0)
                `)
                .call(g => g.append("line")
                    .attr("x2", -5)
                    .attr("stroke", "#000"))
                .call(g => g.append("text")
                    .attr("transform", d => (x(d) + x.bandwidth() / 2 + Math.PI / 2) % (2 * Math.PI) < Math.PI
                        ? "rotate(90)translate(0,16)"
                        : "rotate(-90)translate(0,-9)")
                    .text(d => d));

            // y axis
            svg.append("g")
                .attr("text-anchor", "middle")
                .call(g => g.selectAll("g")
                    .data(y.ticks(5).slice(1))
                    .join("g")
                    .attr("fill", "none")
                    .call(g => g.append("circle")
                        .attr("stroke", "#000")
                        .attr("stroke-opacity", 0.5)
                        .attr("r", y))
                    .call(g => g.append("text")
                        .attr("y", d => -y(d))
                        .attr("dy", "0.35em")
                        .attr("stroke", "#fff")
                        .attr("stroke-width", 5)
                        .text(y.tickFormat(5, "s"))
                    .clone(true)
                        .attr("fill", "#000")
                        .attr("stroke", "none")));

            // color legend
            svg.append("g")
                .selectAll()
                .data(color.domain())
                .join("g")
                .attr("transform", (d, i, nodes) => `translate(-40,${(nodes.length / 2 - i - 1) * 20})`)
                .call(g => g.append("rect")
                    .attr("width", 18)
                    .attr("height", 18)
                    .attr("fill", color))
                .call(g => g.append("text")
                    .attr("x", 24)
                    .attr("y", 9)
                    .attr("dy", "0.35em")
                    .text(d => d));

            const container = document.createElement('div');
            container.style.display = 'flex';
            container.style.alignItems = 'center';
            container.style.flexDirection = 'column';
            container.style.padding = '10px';
            container.appendChild(svg.node())

            return Editor.generateHtml(container);
        },
        args: [config],
        libs: ['d3'],
    }),
};

