data.prepare:
const params = Editor.getParams();

const data = Editor.getLoadedData()['titanic_source_dataset'].result_data[0].rows;

const config = {
    data: data.map(el => ({
        source: el.data[0],
        target: el.data[1],
        value: Number(el.data[2])
    })),
    backgroundColor: params.backgroundColor?.[0] ?? '',
};

module.exports = {
    render: Editor.wrapFn({
        fn: function(dimensions, config) {
            const data = {
                links: config.data,
                nodes: Array.from(new Set(config.data.flatMap(l => [l.source, l.target])), name => ({name, category: name.replace(/ .*/, "")}))
            };
            // Specify the dimensions of the chart.
            const width = dimensions.width;
            const height = dimensions.height;
            const format = d3.format(",.0f");

            // Create a SVG container.
            const svg = d3.create("svg")
                .attr("width", width)
                .attr("height", height)
                .attr("viewBox", [0, 0, width, height])
                .attr("style", "max-width: 100%; height: auto; font: 10px sans-serif;");

            // Constructs and configures a Sankey generator.
            const sankey = d3.sankey()
                .nodeId(d => d.name)
                .nodeAlign(d3.sankeyJustify) // d3.sankeyLeft, etc.
                .nodeWidth(15)
                .nodePadding(10)
                .extent([[1, 5], [width - 1, height - 5]]);

            // Applies it to the data. We make a copy of the nodes and links objects
            // so as to avoid mutating the original.
            const {nodes, links} = sankey({
                nodes: data.nodes.map(d => Object.assign({}, d)),
                links: data.links.map(d => Object.assign({}, d))
            });

            // Defines a color scale.
            const color = d3.scaleOrdinal(d3.schemeCategory10);

            // Creates the rects that represent the nodes.
            const rect = svg.append("g")
                .attr("stroke", "#000")
                .selectAll()
                .data(nodes)
                .join("rect")
                .attr("x", d => d.x0)
                .attr("y", d => d.y0)
                .attr("height", d => d.y1 - d.y0)
                .attr("width", d => d.x1 - d.x0)
                .attr("fill", d => color(d.category));

            // Adds a title on the nodes.
            rect.append("title")
                .text(d => `${d.name}\n${format(d.value)} TWh`);

            // Creates the paths that represent the links.
            const link = svg.append("g")
                .attr("fill", "none")
                .attr("stroke-opacity", 0.5)
                .selectAll()
                .data(links)
                .join("g")
                .style("mix-blend-mode", "multiply");

            link.append("path")
                .attr("d", d3.sankeyLinkHorizontal())
                .attr("stroke", (d) => color(d.source.category))
                .attr("stroke-width", d => Math.max(1, d.width))
                .attr("fill", "none")
                .attr("stroke-opacity", 0.5);

            link.append("title")
                .text(d => `${d.source.name} → ${d.target.name}\n${format(d.value)} TWh`);

            // Adds labels on the nodes.
            svg.append("g")
                .selectAll()
                .data(nodes)
                .join("text")
                .attr("x", d => d.x0 < width / 2 ? d.x1 + 6 : d.x0 - 6)
                .attr("y", d => (d.y1 + d.y0) / 2)
                .attr("dy", "0.35em")
                .attr("text-anchor", d => d.x0 < width / 2 ? "start" : "end")
                .text(d => d.name);

            return Editor.generateHtml(svg.node());
        },
        args: [config],
        libs: ['d3', 'd3-sankey'],
    }),
};

