data.prepare:
const params = Editor.getParams();

const data = Editor.getLoadedData()['population_source_dataset'].result_data[0].rows;

const config = {
    data: data.map(el => ({
        state: el.data[0],
        age: el.data[1],
        population: el.data[2]
    })),
    backgroundColor: params.backgroundColor?.[0] ?? '',
};

module.exports = {
    render: Editor.wrapFn({
        fn: function(dimensions, config) {
            const data = config.data;
            // Specify the chart’s dimensions (except for the height).
            const width = dimensions.width;
            const marginTop = 30;
            const marginRight = 20;
            const marginBottom = 0;
            const marginLeft = 30;

            // Determine the series that need to be stacked.
            const series = d3.stack()
                .keys(d3.union(data.map(d => d.age))) // distinct series keys, in input order
                .value(([, D], key) => D.get(key).population) // get value for each series key and stack
                .offset(d3.stackOffsetExpand)
                (d3.index(data, d => d.state, d => d.age)); // group by stack then series key
            const keys = [];
            data.forEach(el => {
                if (!keys.includes(el.age))
                    keys.push(el.age)
            });

            // Compute the height from the number of stacks.
            const height = series[0].length * 25 + marginTop + marginBottom;

            // Prepare the scales for positional and color encodings.
            const x = d3.scaleLinear()
                .domain([0, d3.max(series, d => d3.max(d, d => d[1]))])
                .range([marginLeft, width - marginRight]);

            const y = d3.scaleBand()
                .domain(d3.groupSort(data, (D) => -D.find(d => d.age === "Under 5 Years").population / d3.sum(D, d => d.population), d => d.state))
                .range([marginTop, height - marginBottom])
                .padding(0.08);


            const color = d3.scaleOrdinal()
                .domain(series.map(d => d.key))
                .range(d3.schemeSpectral[series.length])
                .unknown("#ccc");

            console.log('color: ', color('Under 5 Years'));

            // A function to format the value in the tooltip.
            const formatValue = x => isNaN(x) ? "N/A" : x.toLocaleString("en")

            // Create the SVG container.
            const svg = d3.create("svg")
                .attr("width", width)
                .attr("height", height)
                .attr("viewBox", [0, 0, width, height])
                .attr("style", "max-width: 100%; height: auto;");

            // Append a group for each series, and a rect for each element in the series.
            svg.append("g")
                .selectAll()
                .data(series)
                .join("g")
                .attr("fill", d => color(d.key))
                .selectAll("rect")
                .data(D => D.map(d => (d.key = D.key, d)))
                .join("rect")
                .attr("x", d => x(d[0]))
                .attr("y", d => y(d.data[0]))
                .attr("height", y.bandwidth())
                .attr("width", d => x(d[1]) - x(d[0]))
                .append("title")
                .text(d => `${d.data[0]} ${d.key}\n${formatValue(d.data[1].get(d.key).population)}`);

            // Append the horizontal axis.
            svg.append("g")
                .attr("transform", `translate(0,${marginTop})`)
                .call(d3.axisTop(x).ticks(width / 100, "%"))
                .call(g => g.selectAll(".domain").remove());

            // Append the vertical axis.
            svg.append("g")
                .attr("transform", `translate(${marginLeft},0)`)
                .call(d3.axisLeft(y).tickSizeOuter(0))
                .call(g => g.selectAll(".domain").remove());

            const container = document.createElement('div');
            container.style.display = 'flex';
            container.style.alignItems = 'center';
            container.style.flexDirection = 'column';
            container.style.padding = '10px';
            container.style.height = '100%'

            const legend = document.createElement('div');
            legend.style.display = 'flex';
            legend.style.gap = '10px';
            legend.style.alignSelf = 'flex-start';
            legend.style.flexWrap = 'wrap';
            keys.forEach(age => {
                const legendItem = document.createElement('div');
                legendItem.style.display = 'flex';
                legendItem.style.gap = '5px';
                legendItem.style.alignItems = 'center';

                const legendColor = document.createElement('div');
                legendColor.style.width = '10px';
                legendColor.style.height = '10px';
                legendColor.style.backgroundColor = color(age);

                const legendText = document.createElement('span');
                legendText.textContent = age;

                legendItem.appendChild(legendColor);
                legendItem.appendChild(legendText);
                legend.appendChild(legendItem);
            })
            const svgWrapper = document.createElement('div');
            svgWrapper.style.overflow = 'auto'
            container.appendChild(legend);
            svgWrapper.appendChild(Object.assign(svg.node(), {scales: {color}}))
            container.appendChild(svgWrapper);

            return Editor.generateHtml(container);
        },
        args: [config],
        libs: ['d3'],
    }),
};

