data.prepare:
const params = Editor.getParams();

const config = {
    data: Object.assign([
        [.096899, .008859, .000554, .004430, .025471, .024363, .005537, .025471],
        [.001107, .018272, .000000, .004983, .011074, .010520, .002215, .004983],
        [.000554, .002769, .002215, .002215, .003876, .008306, .000554, .003322],
        [.000554, .001107, .000554, .012182, .011628, .006645, .004983, .010520],
        [.002215, .004430, .000000, .002769, .104097, .012182, .004983, .028239],
        [.011628, .026024, .000000, .013843, .087486, .168328, .017165, .055925],
        [.000554, .004983, .000000, .003322, .004430, .008859, .017719, .004430],
        [.002215, .007198, .000000, .003322, .016611, .014950, .001107, .054264]
    ]),
    names: ["Apple", "HTC", "Huawei", "LG", "Nokia", "Samsung", "Sony", "Other"],
    colors: ["#c4c4c4", "#69b40f", "#ec1d25", "#c8125c", "#008fc8", "#10218b", "#134b24", "#737373"],
    backgroundColor: params.backgroundColor?.[0] ?? '',
};

module.exports = {
    render: Editor.wrapFn({
        fn: function(dimensions, config) {
            function groupTicks(d, step) {
                const k = (d.endAngle - d.startAngle) / d.value;
                return d3.range(0, d.value, step).map(value => {
                    return {value: value, angle: value * k + d.startAngle};
                });
            }

            const container = document.createElement('div');
            container.style.display = 'flex';
            container.style.justifyContent = 'center';

            const width = Math.min(dimensions.width, dimensions.height);
            const height = width;
            console.log('width: ', width)
            const {names, colors} = config;
            console.log('config.data: ', config.data)
            console.log('names: ', names);
            console.log('colors: ', colors);
            const outerRadius = Math.min(width, height) * 0.5 - 40;
            const innerRadius = outerRadius - 10;
            const tickStep = d3.tickStep(0, d3.sum(config.data.flat()), 100);
            const formatValue = d3.format(".1~%");

            const chord = d3.chord()
                .padAngle(10 / innerRadius)
                .sortSubgroups(d3.descending)
                .sortChords(d3.descending);

            const arc = d3.arc()
                .innerRadius(innerRadius)
                .outerRadius(outerRadius);

            const ribbon = d3.ribbon()
                .radius(innerRadius - 1)
                .padAngle(1 / innerRadius);

            const color = d3.scaleOrdinal(names, colors);


            const svg = d3.create("svg")
                .attr("width", width)
                .attr("height", height)
                .attr("viewBox", [-width / 2, -height / 2, width, height])
                .attr("style", "font: 10px sans-serif;")

            const chords = chord(config.data);

            const group = svg.append("g")
                .selectAll()
                .data(chords.groups)
                .join("g");

            group.append("path")
                .attr("fill", d => color(names[d.index]))
                .attr("d", arc);

            group.append("title")
                .text(d => `${names[d.index]}\n${formatValue(d.value)}`);

            const groupTick = group.append("g")
                .selectAll()
                .data(d => groupTicks(d, tickStep))
                .join("g")
                .attr("transform", d => `rotate(${d.angle * 180 / Math.PI - 90}) translate(${outerRadius},0)`);

            groupTick.append("line")
                .attr("stroke", "currentColor")
                .attr("x2", 6);

            groupTick.append("text")
                .attr("x", 8)
                .attr("dy", "0.35em")
                .attr("transform", d => d.angle > Math.PI ? "rotate(180) translate(-16)" : null)
                .attr("text-anchor", d => d.angle > Math.PI ? "end" : null)
                .text(d => formatValue(d.value));

            group.select("text")
                .attr("font-weight", "bold")
                .text(function(d) {
                    return this.getAttribute("text-anchor") === "end"
                        ? `↑ ${names[d.index]}`
                        : `${names[d.index]} ↓`;
                });

            svg.append("g")
                .attr("fill-opacity", 0.8)
                .selectAll("path")
                .data(chords)
                .join("path")
                .style("mix-blend-mode", "multiply")
                .attr("fill", d => color(names[d.source.index]))
                .attr("d", ribbon)
                .append("title")
                .text(d => `${formatValue(d.source.value)} ${names[d.target.index]} → ${names[d.source.index]}${d.source.index === d.target.index ? "" : `\n${formatValue(d.target.value)} ${names[d.source.index]} → ${names[d.target.index]}`}`);

            container.appendChild(svg.node())
            return Editor.generateHtml(container);
        },
        args: [config],
        libs: ['d3'],
    }),
};

const params = Editor.getParams();

const data = Editor.getLoadedData()['flare_source_dataset'].result_data[0].rows;

const config = {
    data: data.map(el => ({
        id: el.data[0],
        value: el.data[1]
    })),
    backgroundColor: params.backgroundColor?.[0] ?? '',
};

module.exports = {
    render: Editor.wrapFn({
        fn: function(dimensions, config) {
            const container = document.createElement('div');
            container.style.display = 'flex';
            container.style.alignItems = 'center';
            container.style.flexDirection = 'column';
            container.style.padding = '10px';

            // Specify the dimensions of the chart.
            const width = Math.min(dimensions.width, dimensions.height - 40);
            const height = width;
            const data = config.data;
            const margin = 1; // to avoid clipping the root circle stroke
            const name = d => d.id.split(".").pop(); // "Strings" of "flare.util.Strings"
            const group = d => d.id.split(".")[1]; // "util" of "flare.util.Strings"
            const names = d => name(d).split(/(?=[A-Z][a-z])|\s+/g); // ["Legend", "Item"] of "flare.vis.legend.LegendItems"

            // Specify the number format for values.
            const format = d3.format(",d");

            // Create a categorical color scale.
            const color = d3.scaleOrdinal(d3.schemeTableau10);

            // Create the pack layout.
            const pack = d3.pack()
                .size([width - margin * 2, height - margin * 2])
                .padding(3);

            // Compute the hierarchy from the (flat) data; expose the values
            // for each node; lastly apply the pack layout.
            const root = pack(d3.hierarchy({children: data})
                .sum(d => d.value));

            // Create the SVG container.
            const svg = d3.create("svg")
                .attr("width", width)
                .attr("height", height)
                .attr("viewBox", [-margin, -margin, width, height])
                .attr("style", "max-width: 100%; height: auto; font: 10px sans-serif;")
                .attr("text-anchor", "middle");

            // Place each (leaf) node according to the layout’s x and y values.
            const node = svg.append("g")
                .selectAll()
                .data(root.leaves())
                .join("g")
                .attr("transform", d => `translate(${d.x},${d.y})`);

            // Add a title.
            node.append("title")
                .text(d => `${d.data.id}\n${format(d.value)}`);

            // Add a filled circle.
            node.append("circle")
                .attr("fill-opacity", 0.7)
                .attr("fill", d => color(group(d.data)))
                .attr("r", d => d.r);

            // Add a label.
            const text = node.append("text")
                .attr("clip-path", d => `circle(${d.r})`);

            // Add a tspan for each CamelCase-separated word.
            text.selectAll()
                .data(d => names(d.data))
                .join("tspan")
                .attr("x", 0)
                .attr("y", (d, i, nodes) => `${i - nodes.length / 2 + 0.35}em`)
                .text(d => d);

            // Add a tspan for the node’s value.
            text.append("tspan")
                .attr("x", 0)
                .attr("y", d => `${names(d.data).length / 2 + 0.35}em`)
                .attr("fill-opacity", 0.7)
                .text(d => format(d.value));
            // return Object.assign(svg.node(), {scales: {color}});
            const legendMap = new Map()
            config.data.forEach(el => {
                if (!legendMap.get(group(el)))
                    legendMap[group(el)] = color(group(el))
            })
            const legend = document.createElement('div');
            legend.style.display = 'flex';
            legend.style.gap = '10px';
            legend.style.alignSelf = 'flex-start';
            legend.style.flexWrap = 'wrap';
            Object.entries(legendMap).forEach(([key, value]) => {
                const legendItem = document.createElement('div');
                legendItem.style.display = 'flex';
                legendItem.style.gap = '5px';
                legendItem.style.alignItems = 'center';

                const legendColor = document.createElement('div');
                legendColor.style.width = '10px';
                legendColor.style.height = '10px';
                legendColor.style.backgroundColor = value;;

                const legendText = document.createElement('span');
                legendText.textContent = key;

                legendItem.appendChild(legendColor);
                legendItem.appendChild(legendText);
                legend.appendChild(legendItem);
            })
            container.appendChild(legend);
            container.appendChild(Object.assign(svg.node(), {scales: {color}}))
            return Editor.generateHtml(container);
        },
        args: [config],
        libs: ['d3'],
    }),
};

