                    "value": 74
                },
                {
                    "name": "Продукт 2",
                    "value": 58
                },
                {
                    "name": "Продукт 3",
                    "value": 45
                },
                {
                    "name": "Продукт 4",
                    "value": 23
                }
            ]
        }
    ],
    backgroundColor: params.backgroundColor?.[0] ?? '',
    showLabels: true
