module.exports = {
    render: Editor.wrapFn({
        fn: function(dimensions, config) {
            const {width, height} = dimensions;

            const CATEGORY_NAMES = [
                "Регион A",
                "Регион B",
                "Регион C",
                "Регион D",
                "Регион E",
            ];
            const SEGMENT_NAMES = [
                "Продукт 1",
                "Продукт 2",
                "Продукт 3",
                "Продукт 4",
            ];

            function buildMarimekko(data) {
                const categoryTotals = data.map((c) =>
                d3.sum(c.segments, (s) => s.value),
                );
                const grandTotal = d3.sum(categoryTotals);

                const rects = [];
                let xCursor = 0;

                data.forEach((cat, i) => {
                const catTotal = categoryTotals[i];
                const catWidth = catTotal / grandTotal;
                let yCursor = 0;

                cat.segments.forEach((seg) => {
                    const segHeight = seg.value / catTotal;
                    rects.push({
                    x0: xCursor,
                    x1: xCursor + catWidth,
                    y0: yCursor,
                    y1: yCursor + segHeight,
                    category: cat.name,
                    segment: seg.name,
                    value: seg.value,
                    share: segHeight,
                    });
                    yCursor += segHeight;
                });

                xCursor += catWidth;
                });

                return rects;
            }

            const root = document.createElement("div");
            root.style.setProperty("font-family", "Arial, sans-serif");
            root.style.setProperty("max-width", `${width}`);
            document.body.appendChild(root);
            document.body.style.setProperty("background", "#fafafa");

            const legend = document.createElement("div");
            legend.style.setProperty("display", "flex");
            legend.style.setProperty("padding", "0px 10px");
            legend.style.setProperty("flex-wrap", "wrap");
            legend.style.setProperty("gap", "14px");
            legend.style.setProperty("margin-bottom", "10px");
            legend.style.setProperty("font-size", "13px");
            root.appendChild(legend);

            const chartHolder = document.createElement("div");
            root.appendChild(chartHolder);

            const margin = { top: 10, right: 20, bottom: 60, left: 20 };
            const innerW = width - margin.left - margin.right;
            const innerH = height - margin.top - margin.bottom;

            const color = d3
                .scaleOrdinal()
                .domain(SEGMENT_NAMES)
                .range(d3.schemeSet2);

            function renderLegend() {
                legend.innerHTML = "";
                SEGMENT_NAMES.forEach((name) => {
                const item = document.createElement("div");
                item.style.setProperty("display", "flex");
                item.style.setProperty("align-items", "center");
                item.style.setProperty("gap", "6px");

                const swatch = document.createElement("span");
                swatch.style.setProperty("width", "12px");
                swatch.style.setProperty("height", "12px");
                swatch.style.setProperty("border-radius", "2px");
                swatch.style.setProperty("background", color(name));
                swatch.style.setProperty("display", "inline-block");

                item.appendChild(swatch);
                item.appendChild(document.createTextNode(name));
                legend.appendChild(item);
                });
            }

            let data = config.data;

            function render() {
                chartHolder.innerHTML = "";

                const rects = buildMarimekko(data);
                const showLabels = config.showLabels;

                const svg = d3
                .select(chartHolder)
                .append("svg")
                .attr("width", width)
                .attr("height", height - 30);

                const g = svg
                .append("g")
                .attr("transform", `translate(${margin.left},${margin.top})`);

                const x = d3.scaleLinear().domain([0, 1]).range([0, innerW]);
                const y = d3.scaleLinear().domain([0, 1]).range([0, innerH]);

                g.selectAll("rect.mekko-seg")
                .data(rects)
                .join("rect")
                .attr("class", "mekko-seg")
                .attr("x", (d) => x(d.x0))
                .attr("y", (d) => y(d.y0))
                .attr("width", (d) => Math.max(0, x(d.x1) - x(d.x0) - 1))
                .attr("height", (d) => Math.max(0, y(d.y1) - y(d.y0) - 1))
                .attr("fill", (d) => color(d.segment))
                .attr("stroke", "#fff")
                .attr("stroke-width", 1)
                .append("title")
                .text(
                    (d) =>
                    `${d.category} / ${d.segment}: ${d.value} (${Math.round(d.share * 100)}%)`,
                );

                if (showLabels) {
                g.selectAll("text.mekko-label")
                    .data(
                    rects.filter(
                        (d) => x(d.x1) - x(d.x0) > 30 && y(d.y1) - y(d.y0) > 16,
                    ),
                    )
                    .join("text")
                    .attr("class", "mekko-label")
                    .attr("x", (d) => (x(d.x0) + x(d.x1)) / 2)
                    .attr("y", (d) => (y(d.y0) + y(d.y1)) / 2)
                    .attr("text-anchor", "middle")
                    .attr("dominant-baseline", "middle")
                    .attr("font-size", "11px")
                    .attr("fill", "#222")
                    .text((d) => `${Math.round(d.share * 100)}%`);
                }

                const categoryTotals = data.map((c) =>
                d3.sum(c.segments, (s) => s.value),
                );
                const grandTotal = d3.sum(categoryTotals);
                let xCursor = 0;

                g.selectAll("text.mekko-cat-label")
                .data(data)
                .join("text")
                .attr("class", "mekko-cat-label")
                .attr("x", (d, i) => {
                    const w = categoryTotals[i] / grandTotal;
                    const cx = x(xCursor) + (x(w) - x(0)) / 2;
                    xCursor += w;
                    return cx;
                })
                .attr("y", innerH + 18)
                .attr("text-anchor", "middle")
                .attr("font-size", "12px")
                .attr("fill", "#333")
                .text((d) => d.name);
            }

            renderLegend();
            render();

            return Editor.generateHtml(root.outerHTML);
        },
        args: [config],
        libs: ['d3'],
    }),
};

